    ctx.register({
      kind: 'tool',
      tool: {
        name: 'sum_values',
        version: '1.0.0',
        description: 'Sum an array of numeric values and return the total.',
        permissions: [],
        sideEffect: 'none',
        parameters: {
          type: 'object',
          properties: {
            numbers: { type: 'array', items: { type: 'number' } }
          },
          required: ['numbers']
